function generalRecordSummary(record){const summary={...record,route:(record.route||[]).map(point=>({latitude:point.latitude,longitude:point.longitude}))};delete summary.courseRoute;delete summary.detailedSamples;delete summary.checkpoints;delete summary.departure;delete summary.destination;delete summary.finalDistanceDifference;delete summary.finalTimeDifference;return summary}
function savePendingRideResult(kind){const pending=pendingRideResult,record=pending?.record;if(!record||pending.readOnly)return false;if(kind==='racing'){const assessment=racingRecordAssessment(record);if(!assessment.eligible){toast(assessment.reason,3200);return false}}try{if(kind==='racing'){if(!profileRepository||!activeProfileId)throw new Error('profile-required');profileRepository.prependRacing(activeProfileId,record,{sameCourse:recordsShareCourse})}else{const summary=generalRecordSummary(record);if(profileRepository&&activeProfileId)profileRepository.prependRide(activeProfileId,summary);else{let rides=[];try{rides=JSON.parse(localStorage.getItem('ridemate_rides')||'[]');if(!Array.isArray(rides))rides=[]}catch{rides=[]}rides.unshift(summary);localStorage.setItem('ridemate_rides',JSON.stringify(rides))}}toast(kind==='racing'?'레이싱 기록으로 저장했습니다.':'일반 기록으로 저장했습니다.');closeRideResult();return true}catch{toast('저장하지 못했습니다. 저장공간을 확인해주세요.',3000);return false}}
