function renderMainMenuProfile(){const profile=profileRepository?.getProfiles().find(item=>item.id===activeProfileId);if(!profile)return;revokeHydratedProfilePhotos();$('#mainMenuProfileAvatar').innerHTML=profileAvatarMarkup(profile.avatar);$('#mainMenuProfileName').textContent=profile.name;hydrateProfilePhotos($('#mainMenuProfileAvatar'))}
function openMainMenu(){const menu=$('#mainMenu');if(!menu.classList.contains('hidden'))return;renderMainMenuProfile();menu.querySelector('[data-menu-item="racing-settings"]')?.classList.toggle('hidden',state.screen!=='racing');menu.querySelector('[data-menu-item="racing-end"]')?.classList.toggle('hidden',state.screen!=='racing'||!['active','countdown','waiting-gps'].includes(state.racingPhase));menu.classList.remove('hidden');menu.setAttribute('aria-hidden','false');history.pushState({...history.state,screen:state.screen,mainMenu:true},'')}
function closeMainMenu(fromHistory=false){const menu=$('#mainMenu');if(menu.classList.contains('hidden'))return;menu.classList.add('hidden');menu.setAttribute('aria-hidden','true');if(!fromHistory&&history.state?.mainMenu){mainMenuHistoryClosing=true;history.back()}}
