function renderRecordRouteMap(record){const container=$('#recordRouteMap');recordRouteLine?.setMap(null);recordRouteLine=null;container.classList.add('hidden');const route=record?.route?.filter(point=>Number.isFinite(point.latitude)&&Number.isFinite(point.longitude));if(!route||route.length<2||typeof kakao==='undefined'||!kakao.maps.Map)return false;container.classList.remove('hidden');const path=route.map(point=>new kakao.maps.LatLng(point.latitude,point.longitude));if(!recordRouteMap)recordRouteMap=new kakao.maps.Map(container,{center:path[0],level:5});recordRouteMap.relayout();recordRouteLine=new kakao.maps.Polyline({map:recordRouteMap,path,strokeWeight:5,strokeColor:'#0a84ff',strokeOpacity:.95});const bounds=new kakao.maps.LatLngBounds();path.forEach(point=>bounds.extend(point));recordRouteMap.setBounds(bounds,24,24,24,24);return true}
function renderRecordDetail(record,racing=false){const detail=$('#recordDetail');renderRecordRouteMap(record);if(!record){detail.classList.add('hidden');detail.innerHTML='';return false}detail.innerHTML=`<button type="button" class="record-detail-close" aria-label="상세 닫기">×</button><h2>${esc(record.name||'주행 기록')}</h2><div class="record-detail-stats"><div><small>거리</small><b>${esc(fmtKm(record.distance||0))}</b></div><div><small>이동 시간</small><b>${esc(formatRidingDuration(record.movingTime??record.elapsedTime??0))}</b></div><div><small>평균 속도</small><b>${esc(fmtSpeed((record.averageMovingSpeed??record.averageSpeed) || 0))}</b></div><div><small>최고 속도</small><b>${esc(fmtSpeed(record.maxSpeed||0))}</b></div></div>${!record.route?.length?'<p>저장된 GPS 경로가 없습니다.</p>':''}${racing?`<p>${record.completed===false?'미완주':'완주'}${Number.isFinite(record.finalDistanceDifference)?` · ${esc(racingComparisonText({distanceDifference:record.finalDistanceDifference,timeDifference:record.finalTimeDifference},'distance').text)}`:''}</p>`:''}`;detail.classList.remove('hidden');detail.querySelector('.record-detail-close').onclick=()=>renderRecordDetail(null);return true}
function renderRecords(kind){const racing=kind==='racing',records=racing?readStoredRacing():readStoredRides();$('#recordsTitle').textContent=racing?'레이싱 기록':'라이딩 기록';renderRecordDetail(null);$('#recordsList').innerHTML=records.map((record,index)=>{const date=new Date(record.endedAt||record.startedAt),dateText=Number.isFinite(date.getTime())?date.toLocaleString('ko-KR'):'날짜 없음',duration=formatRidingDuration(record.elapsedTime??record.duration??0),challenge=racing?`<button class="record-challenge-btn" type="button" data-racing-challenge="${index}">이 기록으로 레이싱</button>`:'';return`<article class="favorite-item"><button class="record-open-btn" type="button" data-record-detail="${index}"><strong>${esc(record.name||dateText)}</strong><span>${esc(fmtKm(record.distance||0))} · ${esc(duration)}</span></button>${challenge}</article>`}).join('')||`<p class="my-places-empty">저장된 ${racing?'레이싱':'라이딩'} 기록이 없습니다.</p>`;$('#recordsList').querySelectorAll('[data-record-detail]').forEach(button=>button.onclick=()=>renderRecordDetail(records[+button.dataset.recordDetail],racing));if(racing)$('#recordsList').querySelectorAll('[data-racing-challenge]').forEach(button=>button.onclick=()=>challengeRacingRecord(+button.dataset.racingChallenge))}
