async function updateAppSetting(control){if(!profileRepository||!activeProfileId)return;const value=control.type==='checkbox'?control.checked:control.value,settings=profileRepository.updateSettings(activeProfileId,{[control.dataset.setting]:value});if(control.dataset.setting==='keepScreenAwake')await wakeLockController?.setEnabled(settings.keepScreenAwake);if(control.dataset.setting==='distanceUnit'){if(state.screen==='route')renderRouteCards();if(state.screen==='navigation')updateNavHud(state.currentLocation);if(state.screen==='riding-board')renderRidingBoard()}}
function activeMyPlaces(){return profileRepository&&activeProfileId?profileRepository.readMyPlaces(activeProfileId):{home:null,work:null,favorites:[]}}
function saveMyPlaces(myPlaces){if(profileRepository&&activeProfileId)profileRepository.writeMyPlaces(activeProfileId,myPlaces);renderMyPlaces()}
function uniquePlaceDetails(place){const values=[place?.name,place?.address].map(value=>String(value||'').trim()).filter(Boolean);return values.filter((value,index)=>values.indexOf(value)===index)}
function savedPlaceDetailsHtml(place,primaryTag='strong',primaryAttribute=''){const[first,...rest]=uniquePlaceDetails(place);return first?`<${primaryTag}${primaryAttribute}>${esc(first)}</${primaryTag}>${rest.map(value=>`<small>${esc(value)}</small>`).join('')}`:''}
function savedPlaceHtml(kind,label,place){return`<h2>${label}</h2>${place?savedPlaceDetailsHtml(place):'<p>등록되지 않았습니다.</p>'}<div class="my-place-actions"><button type="button" data-my-place-set="${kind}">${place?'변경':'등록'}</button>${place?`<button type="button" data-my-place-delete="${kind}">삭제</button>`:''}</div>`}
function renderMyPlaces(){const myPlaces=activeMyPlaces();$('#myPlaceHome').innerHTML=savedPlaceHtml('home','집',myPlaces.home);$('#myPlaceWork').innerHTML=savedPlaceHtml('work','회사',myPlaces.work);$('#myPlacesFavorites').innerHTML=myPlaces.favorites.map(favorite=>`<article class="favorite-item" data-favorite-id="${esc(favorite.id)}"><strong>${esc(favorite.customName)}</strong>${savedPlaceDetailsHtml(favorite.place,'span',' data-favorite-place-name')}<div class="my-place-actions"><button type="button" data-favorite-action="rename" data-favorite-key="${esc(favorite.id)}">이름 변경</button><button type="button" data-favorite-action="location" data-favorite-key="${esc(favorite.id)}">장소 변경</button><button type="button" data-favorite-action="delete" data-favorite-key="${esc(favorite.id)}">삭제</button></div></article>`).join('')||'<p class="my-places-empty">등록된 즐겨찾기가 없습니다.</p>';$$('[data-my-place-set]').forEach(button=>button.onclick=()=>startMyPlaceSelection(button.dataset.myPlaceSet));$$('[data-my-place-delete]').forEach(button=>button.onclick=()=>{const next=activeMyPlaces();next[button.dataset.myPlaceDelete]=null;saveMyPlaces(next)});$$('[data-favorite-action]').forEach(button=>button.onclick=()=>handleFavoriteAction(button.dataset.favoriteAction,button.dataset.favoriteKey))}
function openMyPlaces(){myPlacesBaseScreen=state.screen;closeMainMenu(true);renderMyPlaces();const screen=$('#myPlacesScreen');screen.classList.remove('hidden');screen.setAttribute('aria-hidden','false');history.replaceState({...history.state,screen:myPlacesBaseScreen,mainMenu:false,myPlaces:true},'','#my-places')}
function closeMyPlaces(fromHistory=false){const screen=$('#myPlacesScreen');if(screen.classList.contains('hidden'))return;screen.classList.add('hidden');screen.setAttribute('aria-hidden','true');$('#favoriteEditor').classList.add('hidden');pendingFavoriteEdit=null;if(!fromHistory&&history.state?.myPlaces){myPlacesHistoryClosing=true;history.back()}}
function startMyPlaceSelection(kind,favoriteId=null){myPlaceSelection={kind,favoriteId};$('#myPlacesScreen').classList.add('hidden');openSearch('my-place')}
function completeMyPlaceSelection(place){const selection=myPlaceSelection;if(!selection)return false;const next=activeMyPlaces();if(selection.kind==='home'||selection.kind==='work'){next[selection.kind]=place;profileRepository.writeMyPlaces(activeProfileId,next)}else if(selection.kind==='favorite-location'){const favorite=next.favorites.find(item=>item.id===selection.favoriteId);if(favorite){favorite.place=place;profileRepository.writeMyPlaces(activeProfileId,next)}}else pendingFavoriteEdit={favoriteId:null,place};selection.completed=true;history.back();return true}
function restoreMyPlacesAfterSearch(){cancelSearch();clearSearchMarkers();state.editingEndpoint=null;renderScreen(myPlacesBaseScreen,false);const selection=myPlaceSelection;myPlaceSelection=null;renderMyPlaces();const screen=$('#myPlacesScreen');screen.classList.remove('hidden');screen.setAttribute('aria-hidden','false');if(selection?.completed&&pendingFavoriteEdit)openFavoriteEditor(null,pendingFavoriteEdit.place)}
function openFavoriteEditor(favoriteId=null,place=null){const favorite=favoriteId?activeMyPlaces().favorites.find(item=>item.id===favoriteId):null;pendingFavoriteEdit={favoriteId,place:place||favorite?.place||null};$('#favoriteNameInput').value=favorite?.customName||'';$('#favoriteEditorError').textContent='';$('#favoriteEditor').classList.remove('hidden');setTimeout(()=>$('#favoriteNameInput').focus(),0)}
function closeFavoriteEditor(){pendingFavoriteEdit=null;$('#favoriteEditor').classList.add('hidden');$('#favoriteEditorError').textContent=''}
function handleFavoriteAction(action,favoriteId){const next=activeMyPlaces();if(action==='rename')return openFavoriteEditor(favoriteId);if(action==='location')return startMyPlaceSelection('favorite-location',favoriteId);if(action==='delete'){next.favorites=next.favorites.filter(item=>item.id!==favoriteId);saveMyPlaces(next)}}
function saveFavoriteName(event){event.preventDefault();const customName=$('#favoriteNameInput').value.trim();if(!customName){$('#favoriteEditorError').textContent='이름을 입력해주세요.';return}const next=activeMyPlaces(),edit=pendingFavoriteEdit;if(!edit)return;if(edit.favoriteId){const favorite=next.favorites.find(item=>item.id===edit.favoriteId);if(favorite)favorite.customName=customName}else next.favorites.push({id:`favorite-${Date.now().toString(36)}-${++favoriteSequence}`,customName,place:edit.place});profileRepository.writeMyPlaces(activeProfileId,next);closeFavoriteEditor();renderMyPlaces()}
function renderProfileSelection(model){
  const grid=$('#profileGrid'),empty=$('#profileEmptyState'),selectButton=$('#profileSelectButton');
  if(!grid||!empty||!selectButton)return;
  empty.textContent=model.emptyMessage;
  empty.classList.toggle('hidden',!model.emptyMessage);
  revokeHydratedProfilePhotos();
  grid.innerHTML=model.profiles.map(profile=>{const selected=profile.id===model.selectedProfileId;return`<div class="profile-card-wrapper"><button class="profile-select-control${selected?' selected':''}" type="button" data-profile-select="${esc(profile.id)}" aria-pressed="${selected}">${selected?'<span class="profile-selected-mark" aria-hidden="true">✓</span>':''}${profileAvatarMarkup(profile.avatar)}<strong>${esc(profile.name)}</strong><span class="profile-card-caption">라이딩을 함께 시작해요</span></button><button class="profile-manage-control" type="button" data-profile-manage="${esc(profile.id)}" aria-label="${esc(profile.name)} 프로필 관리">⋯</button></div>`}).join('')+`<button class="profile-add-card" id="profileAddCard" type="button"><span class="profile-plus-circle" aria-hidden="true">＋</span><strong>프로필 추가</strong></button>`;
  hydrateProfilePhotos(grid);
  selectButton.disabled=!model.canSelect;
  grid.querySelectorAll('[data-profile-select]').forEach(button=>button.onclick=()=>profileController.selectProfile(button.dataset.profileSelect));
  grid.querySelectorAll('[data-profile-manage]').forEach(button=>button.onclick=()=>openProfileEditor(button.dataset.profileManage));
  $('#profileAddCard').onclick=()=>openProfileEditor();
}
function showProfileScreen(){activeProfileId=null;wakeLockController?.setEnabled(false);$('#profileScreen')?.classList.remove('hidden');$('#app')?.classList.add('hidden')}
function showMapScreen(){activeProfileId=profileSession.getSelectedProfileId();$('#profileScreen')?.classList.add('hidden');$('#app')?.classList.remove('hidden');wakeLockController?.setEnabled(activeSettings().keepScreenAwake)}
function renderProfileAvatarChoices(selectedIconId='rider'){$('#profileAvatarChoices').innerHTML=Object.entries(PROFILE_AVATARS).map(([iconId,icon])=>`<label class="profile-avatar-option"><input type="radio" name="profileAvatar" value="${iconId}"${iconId===selectedIconId?' checked':''}><span aria-hidden="true">${icon}</span></label>`).join('');$$('input[name="profileAvatar"]').forEach(input=>input.onchange=()=>{if(!input.checked)return;pendingProfileAvatar={type:'icon',iconId:input.value};renderProfilePhotoPreview(pendingProfileAvatar)})}
function revokeProfilePreview(){if(profilePreviewUrl){URL.revokeObjectURL(profilePreviewUrl);profilePreviewUrl=null}}
function renderProfilePhotoPreview(avatar){const preview=$('#profilePhotoPreview'),iconId=avatar?.type==='icon'&&PROFILE_AVATARS[avatar.iconId]?avatar.iconId:'rider',revision=++profilePreviewRevision;revokeProfilePreview();preview.textContent=PROFILE_AVATARS[iconId];if(avatar?.type==='pending-photo'){profilePreviewUrl=URL.createObjectURL(avatar.blob);preview.innerHTML=`<img src="${profilePreviewUrl}" alt="">`}else if(avatar?.type==='photo')hydrateProfilePhoto(preview,avatar.photoId,revision);$('#profilePhotoRemove').classList.toggle('hidden',avatar?.type!=='photo'&&avatar?.type!=='pending-photo')}
function renderProfilePhotoCrop(){if(!profilePhotoCrop)return null;const stage=$('#profilePhotoCropStage'),frameSize=stage.getBoundingClientRect().width||280,crop=globalThis.RideMateSettings.calculateProfilePhotoCrop(profilePhotoCrop.width,profilePhotoCrop.height,frameSize,profilePhotoCrop.zoom,profilePhotoCrop.offsetX,profilePhotoCrop.offsetY),image=$('#profilePhotoCropImage');Object.assign(profilePhotoCrop,{offsetX:crop.offsetX,offsetY:crop.offsetY,crop});image.style.width=`${crop.renderedWidth}px`;image.style.height=`${crop.renderedHeight}px`;image.style.left=`calc(50% + ${crop.offsetX}px)`;image.style.top=`calc(50% + ${crop.offsetY}px)`;$('#profilePhotoCropZoom').value=String(profilePhotoCrop.zoom);return crop}
function beginProfilePhotoCrop(file,url,width,height){profilePhotoCrop={file,url,width,height,zoom:1,offsetX:0,offsetY:0,pointers:new Map(),pinch:null};const image=$('#profilePhotoCropImage'),dialog=$('#profilePhotoCropDialog');image.src=url;$('#profilePhotoCropError').textContent='';dialog.classList.remove('hidden');dialog.setAttribute?.('aria-hidden','false');renderProfilePhotoCrop();return profilePhotoCrop}
function closeProfilePhotoCrop(){if(!profilePhotoCrop)return;globalThis.URL?.revokeObjectURL?.(profilePhotoCrop.url);profilePhotoCrop=null;$('#profilePhotoInput').value='';const dialog=$('#profilePhotoCropDialog');dialog.classList.add('hidden');dialog.setAttribute?.('aria-hidden','true')}
function profilePhotoCropPointerDown(event){if(!profilePhotoCrop)return;event.preventDefault();const point={x:event.clientX,y:event.clientY};profilePhotoCrop.pointers.set(event.pointerId,point);$('#profilePhotoCropStage').setPointerCapture?.(event.pointerId);if(profilePhotoCrop.pointers.size===2){const[a,b]=[...profilePhotoCrop.pointers.values()];profilePhotoCrop.pinch={distance:Math.hypot(b.x-a.x,b.y-a.y)||1,zoom:profilePhotoCrop.zoom}}}
function profilePhotoCropPointerMove(event){if(!profilePhotoCrop||!profilePhotoCrop.pointers.has(event.pointerId))return;event.preventDefault();const previous=profilePhotoCrop.pointers.get(event.pointerId),point={x:event.clientX,y:event.clientY};profilePhotoCrop.pointers.set(event.pointerId,point);if(profilePhotoCrop.pointers.size===1){profilePhotoCrop.offsetX+=point.x-previous.x;profilePhotoCrop.offsetY+=point.y-previous.y}else if(profilePhotoCrop.pointers.size===2&&profilePhotoCrop.pinch){const[a,b]=[...profilePhotoCrop.pointers.values()],distance=Math.hypot(b.x-a.x,b.y-a.y);profilePhotoCrop.zoom=Math.max(1,Math.min(4,profilePhotoCrop.pinch.zoom*distance/profilePhotoCrop.pinch.distance))}renderProfilePhotoCrop()}
function profilePhotoCropPointerUp(event){if(!profilePhotoCrop)return;profilePhotoCrop.pointers.delete(event.pointerId);profilePhotoCrop.pinch=null;$('#profilePhotoCropStage').releasePointerCapture?.(event.pointerId)}
async function applyProfilePhotoCrop(){if(!profilePhotoCrop)return false;const button=$('#profilePhotoCropApply');button.disabled=true;$('#profilePhotoCropError').textContent='';try{const crop=renderProfilePhotoCrop(),blob=await globalThis.RideMateSettings.renderProfilePhotoCrop($('#profilePhotoCropImage'),crop);pendingProfileAvatar={type:'pending-photo',blob};renderProfilePhotoPreview(pendingProfileAvatar);closeProfilePhotoCrop();return true}catch(error){$('#profilePhotoCropError').textContent=error.message;return false}finally{button.disabled=false}}
function wireProfilePhotoCrop(){const stage=$('#profilePhotoCropStage'),slider=$('#profilePhotoCropZoom');stage.addEventListener('pointerdown',profilePhotoCropPointerDown);stage.addEventListener('pointermove',profilePhotoCropPointerMove);stage.addEventListener('pointerup',profilePhotoCropPointerUp);stage.addEventListener('pointercancel',profilePhotoCropPointerUp);stage.addEventListener('lostpointercapture',profilePhotoCropPointerUp);slider.addEventListener('input',event=>{if(!profilePhotoCrop)return;profilePhotoCrop.zoom=Math.max(1,Math.min(4,Number(event.target.value)||1));renderProfilePhotoCrop()});$('#profilePhotoCropCancel').onclick=closeProfilePhotoCrop;$('#profilePhotoCropApply').onclick=applyProfilePhotoCrop}
function openProfileEditor(profileId=null){
  editingProfileId=profileId;
  const profile=profileId?profileRepository.getProfiles().find(item=>item.id===profileId):null;
  $('#profileEditorTitle').textContent=profile?'프로필 수정':'프로필 추가';
  $('#profileNameInput').value=profile?.name||'';
  $('#profileEditorError').textContent='';
  pendingProfileAvatar=profile?.avatar||{type:'icon',iconId:'rider'};
  renderProfileAvatarChoices(pendingProfileAvatar.type==='icon'?pendingProfileAvatar.iconId:'');
  renderProfilePhotoPreview(pendingProfileAvatar);
  $('#profileDeleteButton').classList.toggle('hidden',!profile);
  $('#profileEditor').classList.remove('hidden');
  setTimeout(()=>$('#profileNameInput').focus(),0);
}
function closeProfileEditor(){closeProfilePhotoCrop();editingProfileId=null;pendingProfileAvatar=null;profilePreviewRevision++;revokeProfilePreview();$('#profilePhotoInput').value='';$('#profileEditor').classList.add('hidden');$('#profileEditorError').textContent=''}
async function selectProfilePhoto(file){if(!file?.type?.startsWith('image/')){$('#profileEditorError').textContent='이미지 파일을 선택해주세요.';return false}const url=URL.createObjectURL(file),image=new Image();try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('사진을 불러올 수 없습니다.'));image.src=url});beginProfilePhotoCrop(file,url,image.naturalWidth,image.naturalHeight);return true}catch(error){URL.revokeObjectURL(url);$('#profileEditorError').textContent=error.message;return false}}
async function saveProfileEditor(event){event.preventDefault();const name=$('#profileNameInput').value;let avatar=pendingProfileAvatar||{type:'icon',iconId:'rider'},newPhotoId=null;try{if(avatar.type==='pending-photo'){newPhotoId=await profilePhotoStore.put(avatar.blob);avatar={type:'photo',photoId:newPhotoId}}if(editingProfileId)profileController.updateProfile(editingProfileId,{name,avatar});else profileController.addProfile(name,avatar);closeProfileEditor()}catch(error){if(newPhotoId)profilePhotoStore.delete(newPhotoId).catch(()=>{});$('#profileEditorError').textContent=error.message}}
function wireProfileUi(){
  $('#profileAddTop').onclick=()=>openProfileEditor();
  $('#profileEditorCancel').onclick=closeProfileEditor;
  $('#profileEditorForm').onsubmit=saveProfileEditor;
  $('#profilePhotoSelect').onclick=()=>$('#profilePhotoInput').click();
  $('#profilePhotoInput').onchange=event=>{const file=event.target.files?.[0];if(file)selectProfilePhoto(file)};
  $('#profilePhotoRemove').onclick=()=>{const selected=$('input[name="profileAvatar"]:checked')?.value||'rider';pendingProfileAvatar={type:'icon',iconId:selected};renderProfileAvatarChoices(selected);renderProfilePhotoPreview(pendingProfileAvatar)};
  wireProfilePhotoCrop();
  $('#profileDeleteButton').onclick=()=>{$('#profileEditor').classList.add('hidden');$('#profileDeleteConfirm').classList.remove('hidden')};
  $('#profileDeleteCancel').onclick=()=>{$('#profileDeleteConfirm').classList.add('hidden');$('#profileEditor').classList.remove('hidden')};
  $('#profileDeleteConfirmButton').onclick=()=>{if(editingProfileId)profileController.deleteProfile(editingProfileId);editingProfileId=null;$('#profileDeleteConfirm').classList.add('hidden');$('#profileEditor').classList.add('hidden')};
  $('#profileSelectButton').onclick=async()=>{const button=$('#profileSelectButton');if(button.disabled)return;button.disabled=true;try{await profileController.confirmSelection()}catch(error){button.disabled=false;globalThis.alert?.(`지도를 불러오지 못했습니다. ${error.message}`)}};
}
function bootProfileSelection(){
  const api=globalThis.RideMateProfiles;
  profilePhotoStore=globalThis.RideMateSettings.createProfilePhotoStore(globalThis.indexedDB);
  wakeLockController=globalThis.RideMateSettings.createWakeLockController();
  profileRepository=api.createProfileRepository(localStorage,{onPhotoRemoved:photoId=>profilePhotoStore.delete(photoId).catch(()=>{})});
  profileRepository.initialize();
  profileSession=api.createProfileSession(profileRepository,{startMap:()=>initMap()});
  profileController=api.createProfileController(profileRepository,profileSession,{render:renderProfileSelection,showProfileScreen,showMapScreen});
  wireProfileUi();
  profileController.start();
}

