$('#sheetHandle').addEventListener('pointerdown',e=>{const placeDetail=ui.sheet.classList.contains('place-detail');if(placeDetail&&!['place','navigation-place'].includes(state.screen))return;sheetDrag={start:e.clientY,last:e.clientY,y:sheetY,height:placeSheetHeight||placeSheetCollapsedHeight(),placeDetail,expanded:ui.sheet.classList.contains('place-expanded')};ui.sheet.classList.add('dragging');e.stopPropagation?.();$('#sheetHandle').setPointerCapture(e.pointerId)});
$('#sheetHandle').addEventListener('pointermove',e=>{if(!sheetDrag)return;sheetDrag.last=e.clientY;e.stopPropagation?.();e.preventDefault?.();const h=ui.sheet.offsetHeight;if(sheetDrag.placeDetail){const next=Math.max(120,Math.min(placeSheetExpandedHeight(),sheetDrag.height-(e.clientY-sheetDrag.start)));applyPlaceSheetHeight(next);return}sheetY=Math.max(h*.05,Math.min(h*.75,sheetDrag.y+e.clientY-sheetDrag.start));ui.sheet.style.setProperty('--sheet-y',`${sheetY}px`);setControlBottom(Math.max(90,h-sheetY+18))});
const finishSheetDrag=e=>{if(!sheetDrag)return;const drag=sheetDrag,delta=(Number.isFinite(e?.clientY)?e.clientY:drag.last)-drag.start;sheetDrag=null;ui.sheet.classList.remove('dragging');e?.stopPropagation?.();if(drag.placeDetail){const compact=placeSheetCollapsedHeight(),expanded=placeSheetExpandedHeight();if(!drag.expanded&&delta>=80&&placeSheetHeight<compact-60){history.back()}else if(delta<=-40)setPlaceSheetExpanded(true);else if(drag.expanded&&delta>=40)setPlaceSheetExpanded(false);else if(placeSheetHeight>(compact+expanded)/2)setPlaceSheetExpanded(true);else setPlaceSheetExpanded(false);return}const h=ui.sheet.offsetHeight,ratio=sheetY/h;setSheet(ratio<.25?'high':ratio>.58?'low':'mid')};$('#sheetHandle').addEventListener('pointerup',finishSheetDrag);$('#sheetHandle').addEventListener('pointercancel',finishSheetDrag);$('#sheetHandle').addEventListener('lostpointercapture',finishSheetDrag);

